wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(110903361339663843)
,p_name=>'APEXAPP.PAGE.HOME.HELP.USER'
,p_message_language=>'it'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>Fare clic sul menu dell''utente (<span class="fa fa-user" aria-hidden="true"></span>) nella barra di navigazione (in alto a destra) per accedere al proprio profilo utente e disconnettersi dall''applicazione.<br>',
unistr('Se si fa clic su <strong>Visualizza profilo personale</strong>, \00E8 poi possibile fare clic su <strong>Aggiorna profilo</strong> per immettere i dettagli personali e caricare una foto o un avatar.</p>')))
,p_version_scn=>2564755
);
