,p_name=>'F4050_P158_UPGRADE_NOW'
,p_message_language=>'it'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>%0 %1 \00E8 disponibile. <a rel="noopener noreferrer" href="%2" target="_blank" rel="noopener noreferrer">Leggere l''annuncio</a> per le informazioni sulle novit\00E0 di questa release.</p>'),
unistr('<p>\00C8 possibile iniziare l''upgrade facendo clic sul pulsante Esegui upgrade adesso riportato di seguito. Se non viene eseguita alcuna azione, l''upgrade dell''istanza verr\00E0 effettuato automaticamente il giorno <strong>%3</strong>.</p>')))
,p_version_scn=>2564905
);
