wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(112017675268664171)
,p_name=>'PE.PROPERTY.BROWSER_CACHE.COMPONENT_PROPERTY.PAGE.NULL_TEXT.HELP'
,p_message_language=>'it'
,p_message_text=>'Usa l''impostazione definita negli attributi di sicurezza dell''applicazione.'
,p_version_scn=>2564892
