,p_message_language=>'it'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'',
unistr('<dl><dt>Per fare in modo che venga restituito YES quando il dipendente si trova nel reparto 30 o \00E8 un responsabile (manager):</dt>'),
'<dd><pre>',
'case when ( :P2_DEPTNO = 30 or :P2_JOB = ''MANAGER'' ) then ''YES'' else ''NO'' end',
'</pre></dd>',
'</dl>'))
,p_version_scn=>2564800
);
wwv_flow_imp_shared.create_message(
