);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(111965232749664155)
,p_name=>'PE.PROPERTY.COMPUTATION_PLSQL_EXPRESSION_VARCHAR2.PROMPT'
,p_message_language=>'it'
,p_message_text=>'Espressione PL/SQL'
,p_version_scn=>2564882
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(111235812235663940)
,p_name=>'PE.PROPERTY.COMPUTATION_PLSQL_FUNC_BODY_VARCHAR2.EXAMPLES'
,p_message_language=>'it'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'',
'<dl><dt>Per fare in modo che venga restituito YES quando il dipendente si trova nel reparto 30:</dt>',
'<dd><pre>',
'declare',
'    l_deptno number;',
'begin',
'    select deptno',
'      into l_deptno',
'      from emp',
'     where empno = :P2_EMPNO;',
'',
'    if l_deptno = 30 then',
'        return ''YES'';',
'    else',
'        return ''NO'';',
'    end if;',
'end;',
'</pre></dd>',
'</dl>'))
,p_version_scn=>2564800
);
