,p_name=>'PE.PROPERTY.DB_CREDENTIAL_IS_INSTANCE.HELP'
,p_message_language=>'it'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Abilitare questa opzione per indicare che la credenziale del database scelto \00E8 disponibile a livello di istanza.</p>'),
'<p>Una credenziale del database a livello di istanza deve essere accessibile allo schema del motore APEX (<code>APEX_NNNNNN</code>).</p>'))
,p_version_scn=>2564690
);
wwv_flow_imp_shared.create_message(
