,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'',
unistr('<dl><dt>Per fare in modo che venga restituito YES quando il dipendente si trova nel reparto 30 o \00E8 un responsabile (manager):</dt>'),
'<dd><pre>',
'( apex.env.P2_DEPTNO === "30" || apex.env.P2_JOB === "MANAGER" ? "YES" : "NO" )',
'</pre></dd>',
'</dl>'))
,p_version_scn=>2564800
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(111969139065664156)
,p_name=>'PE.PROPERTY.DEFAULT_VALUE_JS_EXPRESSION_VARCHAR2.HELP'
,p_message_language=>'it'
,p_message_text=>'Immettere l''espressione JavaScript che produce il valore per questo elemento.'
,p_version_scn=>2564883
);
