,p_name=>'PE.PROPERTY.EXTERNAL_FILTER_EXPR.EXAMPLES'
,p_message_language=>'it'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'',
'<dl><dt>Per un servizio REST ORDS, recupero di tutti i record con l''attributo "sal" minore di 3000.</dt>',
'<dd><pre>',
'{"sal": {"$lt": 3000}}',
'</pre></dd>',
'</dl>',
'<dl><dt>Per un servizio REST Oracle Cloud Applications (Saas), recupero di tutti i record con l''attributo "sal" minore di 3000.</dt>',
'<dd><pre>sal &lt; 3000',
'</pre></dd>',
'</dl>'))
,p_version_scn=>2564892
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(112019517108664171)
,p_name=>'PE.PROPERTY.EXTERNAL_FILTER_EXPR.HELP'
,p_message_language=>'it'
,p_message_text=>unistr('Fornire un''espressione di filtro da passare al servizio REST esterno. L''espressione verr\00E0 passata al server remoto senza modifiche. La sintassi dipende dal tipo di origine dati REST. Ad esempio, Oracle REST Data Services (ORDS) prevede la sintassi JS')
||'ON mentre Oracle Cloud Applications (SaaS) prevede un predicato di clausola WHERE simile a SQL che utilizza nomi di attributo filtrabili.'
,p_version_scn=>2564892
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(112019411143664171)
,p_name=>'PE.PROPERTY.EXTERNAL_FILTER_EXPR.PROMPT'
,p_message_language=>'it'
,p_message_text=>'Filtra'
,p_version_scn=>2564892
);
