,p_message_language=>'it'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'',
'    <dl><dt>Per un servizio REST ORDS, ordinamento in base all''attributo "job" con criterio crescente, quindi in base a "ename" con criterio decrescente.</dt>',
'    <dd><pre>',
'    {"job": "asc", "ename": "desc"}',
'    </pre></dd>',
'    </dl>',
'    <dl><dt>Per un servizio REST Oracle Cloud Applications (SaaS), ordinamento in base all''attributo "job" con criterio crescente, quindi in base a "ename" con criterio decrescente.</dt>',
'    <dd><pre>',
'    job:asc,ename:desc',
'    </pre></dd>',
'    </dl>'))
,p_version_scn=>2564892
);
