,p_name=>'PE.PROPERTY.FC_SORT_BY_TOP_COUNTS.HELP'
,p_message_language=>'it'
,p_message_text=>unistr('Specificare se ordinare le voci della lista per il facet o il filtro. Quando l''impostazione \00E8 <strong>Attivo</strong>, le voci della lista vengono ordinate in base al conteggio decrescente. Quando l''impostazione \00E8 <strong>Non attivo</strong>, le voci')
||' della lista vengono visualizzate nell''ordine definito dalla lista di valori.'
,p_version_scn=>2564788
);
wwv_flow_imp_shared.create_message(
