,p_name=>'PE.PROPERTY.FILTER_OPERATORS.LOV.C.D'
,p_message_language=>'it'
,p_message_text=>'Contiene'
,p_version_scn=>2564844
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(111631976827664057)
,p_name=>'PE.PROPERTY.FILTER_OPERATORS.LOV.C.HELP'
,p_message_language=>'it'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>Il filtro restituisce i risultati dei valori di colonna che contengono il valore di filtro impostato.',
unistr('        &PRODUCT_NAME. utilizzer\00E0 <code>column LIKE <strong>%</strong>filtervalue<strong>%</strong></code> nella clausola WHERE.</p>'),
'        <p>Nota: questo operatore impedisce l''uso di qualsiasi indice di colonna, pertanto potrebbe essere eseguita una scansione intera tabella.</p>'))
,p_version_scn=>2564844
);
