wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(111757068473664094)
,p_name=>'PE.PROPERTY.HTML_EXPRESSION.EXAMPLES'
,p_message_language=>'it'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<dl>',
'  <dt>Modifica dei colori dello sfondo e del testo</dt>',
'    <dd><pre>&lt;span style="background-color:yellow; color:red;">#EMPLOYEE_STATUS#&lt;/span></pre></dd>',
'  <dt>Uso dell''intestazione 2</dt>',
'    <dd><pre>&lt;h2>#EMPLOYEE_NAME#&lt;/h2></pre></dd>',
'  <dt>Uso di una classe dinamica dalla query SQL</dt>',
'    <dd><pre>&lt;span class="#COLUMN_CLASS#">#EMPLOYEE_STATUS#&lt;/span></pre><br>',
'    Le stringhe di sostituzione <code>#COLUMN_CLASS#</code> e <code>#EMPLOYEE_STATUS#</code> in questo esempio sono le colonne selezionate nella query SQL del report.</dd>',
'  <dt>Visualizzazione di un''immagine e di una descrizione comandi al passaggio del mouse</dt>',
'    <dd><pre>&lt;img src="#IMAGE_NAME#" title="#EMPLOYEE_NAME#"&gt;</pre></dd>',
'  <dt>Esecuzione del loop sulla lista di valori separata da virgole</dt>',
'    <dd><pre>&lt;ul>{loop "," TAGS/}&lt;li>&APEX$ITEM.&lt;/li>{endloop/}&lt;/ul></pre></dd>',
'  <dt>Uso della direttiva "if" per una colonna con un ID tra apici</dt>',
'    <dd><pre>{if Mixed Case Name/}&lt;strong>#"Mixed Case Name"#&lt;/strong>{endif/}</pre></dd>',
'</dl>'))
,p_version_scn=>2564856
);
