,p_version_scn=>2564824
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(111457116510664006)
,p_name=>'PE.PROPERTY.ICON_VIEW_CUSTOM.HELP'
,p_message_language=>'it'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>Immettere l''HTML delle colonne personalizzate per la vista icone.</p>',
'<p>Sono disponibili le stringhe di sostituzione riportate di seguito.',
'<ul>',
'<li><code>&&lt;COLUMN_NAME&gt;.</code>: stringhe di sostituzione per i nomi delle colonne.</li>',
'<li><code>&&lt;COLUMN_NAME&gt;_LABEL.</code>: stringhe di sostituzione per le etichette delle colonne.</li>',
'<li><code>&APEX$ROW_ID.</code>: identificativo del record per la riga.</li>',
'<li><code>&APEX$ROW_INDEX.</code>: numero sequenza di visualizzazione del record.</li>',
'<li><code>&APEX$ROW_URL.</code>: riferimento alla destinazione collegamento specificata.</li>',
'<li><code>&APEX$ROW_STATE_CLASSES.</code>: stato del record, ad esempio <code>is-inserted</code> o <code>is-deleted</code>.</li>',
'</ul>',
'</p>'))
,p_version_scn=>2564824
);
