wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(110751816341663799)
,p_name=>'PE.PROPERTY.INIT_JAVASCRIPT_FUNCTION.COMPONENT_PROPERTY.CARD.HELP'
,p_message_language=>'it'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Immettere una funzione JavaScript che acquisisca un oggetto opzioni, modifichi l''oggetto e lo restituisca. In questo modo, \00E8 possibile eseguire la personalizzazione avanzata dell''area durante l''inizializzazione. Per le opzioni disponibili, consult')
||'are la documentazione dell''API JavaScript per il widget <code>tableModelView</code>.</p>.',
'<p>',
'Di seguito sono riportate le opzioni aggiuntive definite dall''area Schede:',
'</p>',
'<ul>',
'<li>',
'<strong>modelOptions</strong>: oggetto opzioni passato a <code>apex.model.create</code>.</li>',
'</ul>'))
,p_version_scn=>2564738
);
wwv_flow_imp_shared.create_message(
