,p_message_language=>'it'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<pre>',
'function( options ) {',
'    options.toolbar = false;',
'    return options;',
'}',
'</pre>'))
,p_version_scn=>2564738
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(110751228021663799)
,p_name=>'PE.PROPERTY.INIT_JAVASCRIPT_FUNCTION.COMPONENT_PROPERTY.IG_ATTRIBUTES.HELP'
,p_message_language=>'it'
,p_message_text=>unistr('Immettere una funzione JavaScript che assuma un oggetto di configurazione per la griglia interattiva, modifichi l''oggetto e quindi lo restituisca. Ci\00F2 rende possibile la personalizzazione avanzata dell''aspetto, delle funzioni e del funzionamento dell')
||'a griglia interattiva e di elementi quali la barra degli strumenti, i menu e le azioni.</p>'
,p_version_scn=>2564738
);
wwv_flow_imp_shared.create_message(
