wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(111846419813664120)
,p_name=>'PE.PROPERTY.INIT_POSITION_ZOOM_SOURCE_SQL.EXAMPLES'
,p_message_language=>'it'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>Query che restituisce le colonne NUMBER per determinare la posizione iniziale della mappa e il livello di zoom:</p>',
'<pre>',
'select -133.5 longitude,',
'         35.2 latitude,',
'            3 zoom',
'  from sys.dual',
'</pre>',
'<p>Query che restituisce una colonna SDO_GEOMETRY per determinare la posizione iniziale della mappa e una colonna NUMBER per il livello di zoom.</p>',
'<pre>',
'select sdo_geometry( 2001,                                 -- 2 dimensional point',
'                     4326,                                 -- longitude/latitude (WGS84)',
'                     sdo_point_type( -133.5, 35.2, null ), -- concrete coordinates',
'                     null,                                 -- not used for points',
'                     null                                  -- not used for points',
'       )                   as geometry,',
'       3                   as zoom',
'  from sys.dual',
'</pre>'))
,p_version_scn=>2564870
);
