,p_name=>'PE.PROPERTY.INLINE_CSS.PROMPT'
,p_message_language=>'it'
,p_message_text=>'In linea'
,p_version_scn=>2564764
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(110984745415663866)
,p_name=>'PE.PROPERTY.INLINE_ERROR_NOTIFICATION_TEXT.HELP'
,p_message_language=>'it'
,p_message_text=>unistr('Immettere il messaggio di errore visualizzato quando si verifica un errore in questa pagina. Il messaggio di errore sostituir\00E0 la stringa <code>#NOTIFICATION_MESSAGE#</code> nel modello di pagina.')
