);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(111081273287663894)
,p_name=>'PE.PROPERTY.INLINE_HELP_TEMPLATE.PROMPT'
,p_message_language=>'it'
,p_message_text=>'In linea'
,p_version_scn=>2564779
