 p_id=>wwv_flow_imp.id(110759212800663801)
,p_name=>'PE.PROPERTY.JET_REFERENCE_LINE_COLORS.EXAMPLES'
,p_message_language=>'it'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'',
'<dl>',
'<dt>Lista di colori separata da virgole:</dt>',
'<dd><pre>',
'<strong>rosso,giallo,blu</strong>',
'</pre></dd>',
'<dt>Lista di elementi di pagina o di applicazione sperata da virgole, che restituisce colori. Uso:</dt>',
'<dd><pre>',
'Sintassi: <code>&amp;ITEM.</code>. Ad esempio: <strong><code>&amp;ITEM_1.</code>,<code>&amp;ITEM_2.</code>,<code>&amp;ITEM_3.</code></strong>',
'</pre></dd>',
'<dt>Lista di colonne separata da virgole, che restituisce colori. Uso:</dt>',
'<dd><pre>',
'Sintassi: <code>&amp;COLUMN_NAME.</code>. Ad esempio: <strong><code>&amp;COLUMN_NAME_1.</code>,<code>&amp;COLUMN_NAME_2.</code>,<code>&amp;COLUMN_NAME_3.</code></strong>',
'</pre></dd>',
'</dl>'))
,p_version_scn=>2564739
);
