wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(110465957888663717)
,p_name=>'PE.PROPERTY.LANDMARK_TYPE.COMPONENT_PROPERTY.REGION.ACCESSIBILITY_HELP_TEXT'
,p_message_language=>'it'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Perch\00E9 i tipi di contrassegno sono importanti:'),
'<ul>',
unistr('<li>Chiarit\00E0 e navigazione: ogni tipo indica lo scopo di una sezione specifica e aiuta gli utenti a comprendere ed esplorare la pagina in modo efficace.</li>'),
'<li>Strumenti di accesso facilitato: i lettori di schermo e altre tecnologie assistive si basano su questi contrassegni per offrire contesto e migliorare l''interazione degli utenti.</li>',
'<li>Struttura standardizzata: la scelta del tipo di contrassegno appropriato favorisce un''esperienza di navigazione coerente e intuitiva per tutti gli utenti.</li>',
'</ul>',
'</p>'))
,p_version_scn=>2564701
);
