,p_name=>'PE.PROPERTY.MULTI_VALUE_SEPARATOR.EXAMPLES'
,p_message_language=>'it'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<dl>',
'<dt>Caratteri normali:</dt>',
'<dd><pre>,</pre></dd>',
'<dd><pre>:</pre></dd>',
'<dt>Caratteri di controllo:</dt>',
'<dd>Tabulazione (<em>ASCII: 9</em>) <pre>\t</pre></dd>',
'<dd>Avanzamento riga (<em>ASCII: 10</em>) <pre>\n</pre></dd>',
'<dt>Altri caratteri:</dt>',
'<dd>Utilizzare un valore di codifica Unicode nel formato ''\xxxx'', dove ''xxxx'' indica il valore esadecimale di un carattere nel formato di codifica UCS-2.</dd>',
'<dd>Inizio dell''intestazione (<em>ASCII: 1</em>) <pre>\0001</pre></dd>',
'<dd>Simbolo "@" (<em>ASCII: 64</em>) <pre>\0040</pre></dd>',
'</dl>'))
,p_version_scn=>2564812
);
