,p_message_language=>'it'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'',
unistr('<dl><dt>Per la corretta restituzione dei valori quando il dipendente si trova nel reparto 30 o \00E8 un responsabile (manager):</dt>'),
'<dd><pre>',
'( apex.env.P2_DEPTNO === "30" || apex.env.P2_JOB === "MANAGER" )',
'</pre></dd>',
'</dl>'))
,p_version_scn=>2564799
);
wwv_flow_imp_shared.create_message(
