,p_message_language=>'it'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'',
unistr('<dl><dt>Per la corretta restituzione dei valori se esistono una o pi\00F9 righe durante il controllo per determinare se il dipendente si trova nel reparto 30:</dt>'),
'<dd><pre>',
'select 1',
'  from emp',
' where empno  = :P2_EMPNO',
'   and deptno = 30',
'</pre></dd>',
'<dt>Per la corretta restituzione dei valori se non esistono righe durante il controllo per determinare se il dipendente si trova nel reparto 40:</dt>',
'<dd><pre>',
'select 1',
'  from emp',
' where empno  = :P2_EMPNO',
'   and deptno = 40',
'</pre></dd>',
'</dl>'))
,p_version_scn=>2564799
);
