wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(111240891440663942)
,p_name=>'PE.PROPERTY.SHORTCUT_JS_FUNC_BODY_VARCHAR2.EXAMPLES'
,p_message_language=>'it'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'',
'<dl><dt>Per fare in modo che venga restituito YES quando il dipendente si trova nel reparto 30:</dt>',
'<dd><pre>',
'let deptno,',
'    rows;',
'',
'rows = apex.conn.execute( "select deptno from emp empno = :1", [ apex.env.P2_EMPNO ] ).rows;',
'for (let row of rows) {',
'  deptno = row.DEPTNO;',
'}',
'',
'return ( deptno === 30 ? "YES", "NO" );',
'</pre></dd>',
'</dl>'))
,p_version_scn=>2564800
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(111435442447664000)
,p_name=>'PE.PROPERTY.SHORTCUT_JS_FUNC_BODY_VARCHAR2.PROMPT'
,p_message_language=>'it'
,p_message_text=>'Corpo funzione JavaScript'
,p_version_scn=>2564821
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(111240715462663942)
,p_name=>'PE.PROPERTY.SHORTCUT_PLSQL_FUNC_BODY_VARCHAR2.EXAMPLES'
,p_message_language=>'it'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'',
'<dl><dt>Per fare in modo che venga restituito YES quando il dipendente si trova nel reparto 30:</dt>',
'<dd><pre>',
'declare',
'    l_deptno number;',
'begin',
'    select deptno',
'      into l_deptno',
'      from emp',
'     where empno = :P2_EMPNO;',
'',
'    if l_deptno = 30 then',
'        return ''YES'';',
'    else',
'        return ''NO'';',
'    end if;',
'end;',
'</pre></dd>',
'</dl>'))
,p_version_scn=>2564800
);
