,p_message_language=>'it'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'',
'<dl><dt>Stampare la lista dei nomi di tutti i dipendenti con le relative mansioni:</dt>',
'<dd><pre>',
'let result = "&lt;h4&gt;Lista di dipendenti:&lt;/h4&gt;";',
'let rows = apex.conn.execute( `',
'    select ename,',
'           job',
'      from emp',
'     order by ename',
'` ).rows;',
'',
'result += "&lt;ul&gt;";',
'for ( let row of rows ) {',
'    result += `&lt;li&gt;&lt;strong&gt;${row.ENAME}&lt;/strong&gt; (${row.JOB})&lt;/li&gt;`;',
'}',
'result += "&lt;/ul&gt;";',
'',
'return result;',
'</pre></dd>',
'</dl>'))
,p_version_scn=>2564800
);
