,p_message_language=>'it'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'',
unistr('<dl><dt>Per la corretta restituzione dei valori quando il dipendente si trova nel reparto 30 o \00E8 un responsabile (manager):</dt>'),
'<dd><pre>',
'( apex.env.P2_DEPTNO === "30" || apex.env.P2_JOB === "MANAGER" )',
'</pre></dd>',
'</dl>'))
,p_version_scn=>2564800
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(111445427460664003)
,p_name=>'PE.PROPERTY.SO_COND_CONDITION_JS_EXPRESSION_BOOLEAN.PROMPT'
,p_message_language=>'it'
,p_message_text=>'Espressione JavaScript'
,p_version_scn=>2564822
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(111243745584663943)
,p_name=>'PE.PROPERTY.SO_COND_CONDITION_JS_FUNC_BODY_BOOLEAN.EXAMPLES'
,p_message_language=>'it'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'',
'<dl><dt>Per la corretta restituzione dei valori quando il dipendente si trova nel reparto 30:</dt>',
'<dd><pre>',
'let deptno,',
'    rows;',
'',
'rows = apex.conn.execute( "select deptno from emp empno = :1", [ apex.env.P2_EMPNO ] ).rows;',
'for (let row of rows) {',
'  deptno = row.DEPTNO;',
'}',
'',
'return ( deptno === 30 );',
'</pre></dd>',
'</dl>'))
,p_version_scn=>2564800
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(111445871254664003)
