,p_version_scn=>2564800
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(111445372619664003)
,p_name=>'PE.PROPERTY.SO_COND_CONDITION_PLSQL_EXPRESSION_BOOLEAN.PROMPT'
,p_message_language=>'it'
