,p_name=>'PE.PROPERTY.VALUE_SQL_EXPRESSION_CUSTOM.EXAMPLES'
,p_message_language=>'it'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'',
unistr('<dl><dt>Per fare in modo che venga restituito YES quando il dipendente \00E8 un responsabile (manager) e il relativo reparto si trova a Chicago:</dt>'),
'<dd><pre>',
'case',
'when :P2_JOB = ''MANAGER'' and',
'     exists ( select 1',
'                from dept',
'               where deptno = :P2_DEPTNO',
'                 and loc    = ''CHICAGO'' ) then ''YES''',
'else ''NO''',
'end',
'</pre></dd>',
'</dl>'))
,p_version_scn=>2564800
);
