,p_name=>'PE.PROPERTY.WF_CONDITION_JS_EXPRESSION_BOOLEAN.EXAMPLES'
,p_message_language=>'it'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'',
unistr('<dl><dt>Per la corretta restituzione dei valori quando il dipendente si trova nel reparto 30 o \00E8 un responsabile (manager):</dt>'),
'<dd><pre>',
'( apex.env.P2_DEPTNO === "30" || apex.env.P2_JOB === "MANAGER" )',
'</pre></dd>',
'</dl>'))
,p_version_scn=>2564800
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(110948216546663856)
,p_name=>'PE.PROPERTY.WF_CONDITION_JS_EXPRESSION_BOOLEAN.HELP'
,p_message_language=>'it'
