,p_name=>'PE.PROPERTY.WF_CONDITION_JS_EXPRESSION_BOOLEAN.PROMPT'
,p_message_language=>'it'
,p_message_text=>'Espressione JavaScript'
,p_version_scn=>2564762
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(111245162175663943)
,p_name=>'PE.PROPERTY.WF_CONDITION_JS_FUNC_BODY_BOOLEAN.EXAMPLES'
,p_message_language=>'it'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'',
'<dl><dt>Per la corretta restituzione dei valori quando il dipendente si trova nel reparto 30:</dt>',
'<dd><pre>',
'let deptno,',
'    rows;',
'',
'rows = apex.conn.execute( "select deptno from emp empno = :1", [ apex.env.P2_EMPNO ] ).rows;',
'for (let row of rows) {',
'  deptno = row.DEPTNO;',
'}',
'',
'return ( deptno === 30 );',
'</pre></dd>',
'</dl>'))
,p_version_scn=>2564800
);
