wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(110681636152663779)
,p_name=>'WWV_FLOW_CUSTOM_AUTH_STD.ACTION1'
,p_message_language=>'it'
,p_message_text=>unistr('La funzione di sentry di pagina restituir\00E0 il risultato booleano del controllo per la verifica delle sessioni incorporato al motore. Se il risultato \00E8 true, il motore continuer\00E0 a visualizzare o accettare la pagina. Se il risultato \00E8 false, il motore')
||unistr(' eseguir\00E0 il reindirizzamento alla pagina o all''URL di sessione non valida specificato in questo schema di autenticazione (vedere di seguito).')
,p_version_scn=>2564730
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(110682914710663780)
,p_name=>'WWV_FLOW_CUSTOM_AUTH_STD.ACTION10'
,p_message_language=>'it'
,p_message_text=>unistr('Se la funzione di sentry di pagina restituisce TRUE, il rendering o l''elaborazione della pagina continua. Se il risultato \00E8 FALSE, il motore deve uscire perch\00E9 non \00E8 specificata nessuna destinazione di sessione non valida nello schema di autenticazio')
||'ne. In questo caso, si presume che la funzione di sentry di pagina fornita dall''utente abbia eseguito il reindirizzamento a una pagina di login al di fuori dell''ambiente %0, possibilmente a un portale di autenticazione esterno. La funzione dovrebbe a'
||'vere anche impostato la variabile globale g_unrecoverable_error := true per inviare al motore l''istruzione di uscire senza visualizzare una pagina di errore.'
,p_version_scn=>2564730
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(110683059885663780)
,p_name=>'WWV_FLOW_CUSTOM_AUTH_STD.ACTION11'
,p_message_language=>'it'
,p_message_text=>unistr('Il motore eseguir\00E0 il codice seguente specificato come processo di pre-autenticazione di questo schema di autenticazione:')
,p_version_scn=>2564730
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(110683161211663780)
,p_name=>'WWV_FLOW_CUSTOM_AUTH_STD.ACTION12'
,p_message_language=>'it'
,p_message_text=>'Questo viene eseguito come blocco anonimo che non restituisce nessun valore.'
,p_version_scn=>2564730
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(110683225062663780)
,p_name=>'WWV_FLOW_CUSTOM_AUTH_STD.ACTION13'
,p_message_language=>'it'
,p_message_text=>unistr('Non \00E8 specificato nessun codice di pre-autenticazione in questo schema.')
,p_version_scn=>2564730
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(110683477013663780)
,p_name=>'WWV_FLOW_CUSTOM_AUTH_STD.ACTION14'
,p_message_language=>'it'
,p_message_text=>unistr('Qualsiasi combinazione di nome utente e password immessa nel form di login sar\00E0 considerata valida. Il nome utente immesso verr\00E0 utilizzato come nome dell''utente collegato per la durata della sessione. Questa tecnica pu\00F2 essere utile durante lo svilu')
||'ppo dell''applicazione ma prima che vengano stabiliti gli account utente effettivi.'
,p_version_scn=>2564730
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(110683597565663780)
,p_name=>'WWV_FLOW_CUSTOM_AUTH_STD.ACTION15'
,p_message_language=>'it'
,p_message_text=>unistr('Controllare il nome utente e la password immessi nel form di login con gli account (utente cookie) dell''App Builder. Questi sono gli stessi account utilizzati nell''area di lavoro per eseguire il login a %0. Questa tecnica pu\00F2 essere utile quando gli ')
||'utenti dell''applicazione sono sviluppatori con %0 account nello stesso database e nella stessa area di lavoro.'
,p_version_scn=>2564730
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(110610065801663759)
,p_name=>'WWV_FLOW_CUSTOM_AUTH_STD.ACTION15A'
,p_message_language=>'it'
,p_message_text=>unistr('Controllare il nome utente e la password immessi nel form di login rispetto agli account di database Oracle. Questa tecnica pu\00F2 essere utile quando gli utenti dell''applicazione dispongono di account nel database.')
,p_version_scn=>2564720
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(110683677020663780)
,p_name=>'WWV_FLOW_CUSTOM_AUTH_STD.ACTION16'
,p_message_language=>'it'
,p_message_text=>'Controllare il nome utente e la password immessi nel form di login utilizzando la directory LDAP specificata in questo schema di autenticazione.'
,p_version_scn=>2564730
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(110683752290663780)
,p_name=>'WWV_FLOW_CUSTOM_AUTH_STD.ACTION17'
,p_message_language=>'it'
,p_message_text=>'I parametri LDAP sono impostati su:'
,p_version_scn=>2564730
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(110684495211663780)
,p_name=>'WWV_FLOW_CUSTOM_AUTH_STD.ACTION18'
,p_message_language=>'it'
,p_message_text=>'Eseguire il codice personalizzato seguente per verificare le credenziali:'
,p_version_scn=>2564731
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(110684698503663780)
,p_name=>'WWV_FLOW_CUSTOM_AUTH_STD.ACTION19'
,p_message_language=>'it'
,p_message_text=>unistr('Controllare la tabella di sessioni incorporate per la sessione utilizzata dalla pagina di login incorporata. Se la sessione esiste e non \00E8 di propriet\00E0 di un altro utente, contrassegnarla come di propriet\00E0 dell''utente autenticato (utilizzando il nome')
||' utente del form di login).'
,p_version_scn=>2564731
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(110681772755663779)
,p_name=>'WWV_FLOW_CUSTOM_AUTH_STD.ACTION2'
,p_message_language=>'it'
,p_message_text=>unistr('La funzione di sentry di pagina restituir\00E0 il risultato booleano del controllo per la verifica delle sessioni incorporato accoppiato con il risultato del controllo per la verifica fornito dall''utente al motore. Se il risultato \00E8 true, il motore conti')
||unistr('nuer\00E0 a mostrare o accettare la pagina. Se il risultato \00E8 false, il motore eseguir\00E0 il reindirizzamento alla destinazione di sessione non valida specificata in questo schema di autenticazione (vedere di seguito).')
,p_version_scn=>2564730
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(110684770896663780)
,p_name=>'WWV_FLOW_CUSTOM_AUTH_STD.ACTION20'
,p_message_language=>'it'
,p_message_text=>'Impostare il cookie denominato %0 su un valore che individui la riga nella tabella di sessioni interne.'
,p_version_scn=>2564731
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(110684809120663780)
,p_name=>'WWV_FLOW_CUSTOM_AUTH_STD.ACTION22'
,p_message_language=>'it'
,p_message_text=>unistr('Determinare l''URL per il reindirizzamento successivo. Se \00E8 stato registrato un "deep link" nello stato di sessione dal motore dipresentazione, utilizzare tale link come URL a cui passare, altrimenti passare all''URL specificato come attributo di colle')
||'gamento alla home dell''applicazione.'
,p_version_scn=>2564731
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(110685027825663780)
,p_name=>'WWV_FLOW_CUSTOM_AUTH_STD.ACTION23'
,p_message_language=>'it'
,p_message_text=>unistr('Dopo la verifica delle credenziali, il motore eseguir\00E0 il seguente codice specificato come processo di post-autenticazione di questo schema di autenticazione:')
,p_version_scn=>2564731
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(110685185373663780)
,p_name=>'WWV_FLOW_CUSTOM_AUTH_STD.ACTION24'
,p_message_language=>'it'
,p_message_text=>'Questo viene eseguito come blocco anonimo che non restituisce nessun valore.'
,p_version_scn=>2564731
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(110685217099663780)
,p_name=>'WWV_FLOW_CUSTOM_AUTH_STD.ACTION25'
,p_message_language=>'it'
,p_message_text=>'Nessun codice di post-autenticazione specificato in questo schema.'
,p_version_scn=>2564731
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(110685333690663780)
,p_name=>'WWV_FLOW_CUSTOM_AUTH_STD.ACTION26'
,p_message_language=>'it'
,p_message_text=>'Eseguire il reindirizzamento all''URL determinato sopra. Questo segna la fine dell''elaborazione login utilizzando la pagina di login incorporata e le API chiamate dalla pagina.'
,p_version_scn=>2564731
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(110681898421663779)
,p_name=>'WWV_FLOW_CUSTOM_AUTH_STD.ACTION3'
,p_message_language=>'it'
,p_message_text=>unistr('Utilizzare la logica personalizzata per eseguire i task di sentry di pagina. Per ciascuna richiesta di pagina, il motore eseguir\00E0 il codice seguente:')
,p_version_scn=>2564730
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(110681992610663779)
,p_name=>'WWV_FLOW_CUSTOM_AUTH_STD.ACTION4'
,p_message_language=>'it'
,p_message_text=>unistr('Il risultato booleano del blocco precedente verr\00E0 restituito al motore. Se il risultato \00E8 true, il motore continuer\00E0 a mostrare o accettare la pagina. Se il risultato \00E8 false, il motore eseguir\00E0 il reindirizzamento alla destinazione di sessione non v')
||'alida specificata in questo schema di autenticazione (vedere di seguito).'
,p_version_scn=>2564730
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(110682024875663779)
,p_name=>'WWV_FLOW_CUSTOM_AUTH_STD.ACTION5'
,p_message_language=>'it'
,p_message_text=>unistr('Il metodo incorporato per la verifica delle sessioni \00E8 disponibile per lo sviluppatore %0 che utilizza la chiamata API:')
,p_version_scn=>2564730
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(110682144622663779)
,p_name=>'WWV_FLOW_CUSTOM_AUTH_STD.ACTION6'
,p_message_language=>'it'
,p_message_text=>unistr('Questo risultato di funzione booleano pu\00F2 essere combinato ad altri controlli nella funzione di sentry di pagina fornita dall''utente, specificata in uno schema di autenticazione. Se si richiama questa API, verr\00E0 controllato il cookie denominato %0')
,p_version_scn=>2564730
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(110682226281663779)
,p_name=>'WWV_FLOW_CUSTOM_AUTH_STD.ACTION7'
,p_message_language=>'it'
,p_message_text=>'Se il cookie esiste e il suo valore decodificato individua una riga nella tabella di sessioni interne, la sessione viene considerata valida e viene restituito un valore TRUE alla funzione di sentry di pagina che l''ha richiamata.'
,p_version_scn=>2564730
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(110682458044663779)
,p_name=>'WWV_FLOW_CUSTOM_AUTH_STD.ACTION8'
,p_message_language=>'it'
,p_message_text=>unistr('Se la funzione di sentry di pagina restituisce TRUE, il rendering o l''elaborazione della pagina continua. Se il risultato \00E8 FALSE, il motore mostrer\00E0 la pagina %0, considerata la pagina di login di questa applicazione in base alla sua designazione ne')
||'llo schema di autenticazione come pagina di sessione non valida.'
,p_version_scn=>2564730
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(110682896857663780)
,p_name=>'WWV_FLOW_CUSTOM_AUTH_STD.ACTION9'
,p_message_language=>'it'
,p_message_text=>unistr('La funzione di sentry di pagina restituisce un risultato booleano al motore. Se il risultato \00E8 TRUE, il rendering o l''elaborazione della pagina continua. Se il risultato \00E8 FALSE, il motore eseguir\00E0 il reindirizzamento a %0')
,p_version_scn=>2564730
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(110685453156663780)
,p_name=>'WWV_FLOW_CUSTOM_AUTH_STD.API_COMMON1'
,p_message_language=>'it'
,p_message_text=>'Un approccio tipico fa in modo che la pagina contenga un form di login per acquisire le credenziali dell''utente. Quindi i processi successivi alla sottomissione della pagina richiamano un modulo di autenticazione per verificare le credenziali. Dopo l'
||'''autenticazione, la pagina esegue qualsiasi task di registrazione delle sessioni e di impostazione dei cookie e infine esegue il reindirizzamento alla pagina iniziale dell''applicazione.'
,p_version_scn=>2564731
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(110685530881663780)
,p_name=>'WWV_FLOW_CUSTOM_AUTH_STD.API_COMMON2'
,p_message_language=>'it'
,p_message_text=>unistr('La procedura %0 API: wwv_flow_custom_auth_std pu\00F2 essere richiamata da tali processi successivi alla sottomissione per eseguire qualsiasi passo appena descritto. Sono disponibili due punti di accesso:')
,p_version_scn=>2564731
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(110685669069663780)
,p_name=>'WWV_FLOW_CUSTOM_AUTH_STD.API_COMMON3'
,p_message_language=>'it'
,p_message_text=>unistr('Richiamare la procedura di login per fare in modo che il motore esegua automaticamente tutti i passi. Il motore utilizzer\00E0 la tabella di sessioni incorporate ed eseguir\00E0 la registrazione delle sessioni e l''impostazione dei cookie. Il codice personali')
||unistr('zzato fornito dall''utente in questo schema di autenticazione verr\00E0 eseguito nei punti di pre-autenticazione, autenticazione o post-autenticazione.')
,p_version_scn=>2564731
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(110685755058663780)
,p_name=>'WWV_FLOW_CUSTOM_AUTH_STD.API_COMMON4'
,p_message_language=>'it'
,p_message_text=>unistr('Richiamare la procedura post_login se si esegue l''autenticazione di persona ma si desidera che %0 gestisca tutte le attivit\00E0 di post-autenticazione. Con questi due punti di accesso \00E8 possibile utilizzare qualsiasi passo di elaborazione login incorpor')
||'ato in combinazione con la propria pagina di login e con i processi in esecuzione su tale pagina. Ricordare che l''uso dell''elaborazione post-autenticazione incorporata consente di utilizzare anche l''elaborazione di sentry di pagina e di verifica dell'
||'e sessioni incorporata.'
,p_version_scn=>2564731
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(110682580401663779)
,p_name=>'WWV_FLOW_CUSTOM_AUTH_STD.BUILTIN_LOGIN_PG'
,p_message_language=>'it'
,p_message_text=>'la pagina di login incorporata'
,p_version_scn=>2564730
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(110685845442663780)
,p_name=>'WWV_FLOW_CUSTOM_AUTH_STD.CHART_LOGIN1'
,p_message_language=>'it'
,p_message_text=>'Elaborazione login esterno'
,p_version_scn=>2564731
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(110686672100663781)
,p_name=>'WWV_FLOW_CUSTOM_AUTH_STD.CHART_LOGIN12'
,p_message_language=>'it'
,p_message_text=>unistr('L''URL di login %0 non appare per specificare una pagina dell''applicazione %1 come destinazione di sessione non valida. Inoltre non esistono valori di elaborazione login nello schema di autenticazione. Questa pagina \00E8 responsabile dell''esecuzione dei ')
||'seguenti passi:'
,p_version_scn=>2564731
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(110686736416663781)
,p_name=>'WWV_FLOW_CUSTOM_AUTH_STD.CHART_LOGIN13'
,p_message_language=>'it'
,p_message_text=>unistr('Notare che se i servizi richiamati in questo URL non utilizzano l''API %0 wwv_custom_auth_std per assistere i task di registrazione di sessione, l''applicazione non potr\00E0 utilizzare il sentry di pagina incorporato o l''elaborazione della verifica delle ')
||'sessioni. Tali operazioni dovranno essere eseguite con metodi stabiliti dall''utente.'
,p_version_scn=>2564731
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(110687091743663781)
,p_name=>'WWV_FLOW_CUSTOM_AUTH_STD.CHART_LOGIN14'
,p_message_language=>'it'
,p_message_text=>unistr('L''URL di login %0 non appare per specificare una pagina dell''applicazione %1 come destinazione di sessione non valida. Questa pagina \00E8 responsabile dell''esecuzione dei seguenti passi:')
,p_version_scn=>2564731
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(110687138892663781)
,p_name=>'WWV_FLOW_CUSTOM_AUTH_STD.CHART_LOGIN15'
,p_message_language=>'it'
,p_message_text=>'I valori impostati per l''elaborazione del login nello schema di autenticazione sono mostrati di seguito:'
,p_version_scn=>2564731
);
wwv_flow_imp_shared.create_message(
