,p_is_translatable=>false
,p_depending_on_attribute_id=>wwv_flow_imp.id(1901267720643867.4415)
,p_depending_on_has_to_exist=>true
,p_depending_on_condition_type=>'EQUALS'
,p_depending_on_expression=>'PAGE_NUMBER_FIXED_SIZE'
