wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(708300825765129776.4415)
,p_plugin_id=>wwv_flow_imp.id(707764939992010930.4415)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>7
,p_display_sequence=>70
,p_prompt=>'Funzione di modifica nome utente LDAP'
,p_attribute_type=>'PLSQL FUNCTION BODY'
,p_is_required=>false
,p_is_translatable=>false
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
unistr('\00C8 possibile fornire codice aggiuntivo da eseguire per trasformare il nome utente in un formato idoneo per la voce di directory LDAP o per il nome utente LDAP.'),
'La bind variable :USERNAME contiene il nome specificato dall''utente finale.',
'Ad esempio, il codice seguente richiama una funzione che sostituisce tutte le occorrenze di "."'' con "_"'' nella stringa DN:</p>',
'',
'<p><pre>',
'return apex_custom_auth.ldap_dnprep(p_username => :USERNAME);',
'</pre></p>',
'',
unistr('<p>&PRODUCT_NAME. utilizzer\00E0 la funzione di escape per il nome utente restituito in base all''attributo di autenticazione <strong>Escape nome utente</strong>.')))
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(38288205752186126.4415)
,p_plugin_id=>wwv_flow_imp.id(707764939992010930.4415)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>8
,p_display_sequence=>80
,p_prompt=>'Escape nome utente'
,p_attribute_type=>'SELECT LIST'
,p_is_required=>true
,p_default_value=>'STD'
,p_is_translatable=>false
,p_lov_type=>'STATIC'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'Prima di sostituire <strong>%LDAP_USER%</strong> nel nome distinto e nella stringa di ricerca LDAP,',
unistr('&PRODUCT_NAME. pu\00F2 applicare automaticamente il valore di escape ai caratteri speciali presenti nel nome utente.'),
'<p/>',
'Di seguito sono riportate le regole di escape possibili.',
'<ul>',
'<li><strong>Standard</strong>:',
'applica la funzione di escape ai caratteri speciali in base a RFC 4514 (per i nomi distinti) e a RFC 4515 (per le stringhe di ricerca).',
'La funzione di escape viene applicata anche ai caratteri Unicode.',
unistr('Si tratta dell''impostazione pi\00F9 sicura, che tuttavia pu\00F2 creare problemi con alcuni server LDAP.</li>'),
'<li><strong>Solo caratteri speciali</strong>:',
'applica la funzione di escape ai caratteri speciali in base a RFC 4514 (per i nomi distinti) e a RFC 4515 (per le stringhe di ricerca).',
'Non applica la funzione di escape ai caratteri Unicode.</li>',
'<li><strong>Nessuna funzione di escape</strong>:',
'non applica la funzione di escape ad alcun carattere.',
unistr('Questa impostazione \00E8 potenzialmente non sicura,'),
'a meno che non sia utilizzata la <strong>Funzione di modifica del nome utente</strong> che applica',
unistr('gi\00E0 la funzione di escape al nome utente (ad esempio con apex_escape.ldap_dn or apex_escape.ldap_search_filter).</li>'),
'</ul>'))
);
wwv_flow_imp_shared.create_plugin_attr_value(
 p_id=>wwv_flow_imp.id(38288513717188434.4415)
,p_plugin_attribute_id=>wwv_flow_imp.id(38288205752186126.4415)
,p_display_sequence=>10
,p_display_value=>'Standard'
,p_return_value=>'STD'
