 p_id=>wwv_flow_imp.id(3112575602612766963.4415)
,p_plugin_id=>wwv_flow_imp.id(1630055805138100682.4415)
,p_name=>'INIT_JAVASCRIPT_CODE'
,p_is_required=>false
,p_depending_on_has_to_exist=>true
,p_examples=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<pre><code>function(options){',
'    // disable the Autoformat feature',
'    options.editorOptions.removePlugins.push( "Autoformat" );',
'    // apply a custom toolbar',
'    options.editorOptions.toolbar = [ "heading", "bulletedList", "numberedList", "fontSize", "undo", "redo" ];',
'    return options;',
'}</code></pre>'))
,p_help_text=>'Immettere una funzione JavaScript per sostituire la configurazione dell''editor standard.'
);
