,p_examples=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<dl><dt>Aumento dello stipendio del 3% per i dipendenti qualificati per l''aumento:</dt>',
'<dd><pre>',
'begin',
'    for l_emp ( select empno',
'                  from emp',
'                 where deptno = :P2_DEPTNO )',
'    loop',
'        if needs_salary_raise( l_empno.empno ) then',
'            update emp',
'               set sal = sal * 1.03',
'             where empno = l_emp.empno;',
'        end if;',
'    end loop;',
'end;',
'</pre></dd>',
'</dl>',
unistr('<p>Per questo esempio \00E8 necessario immettere <code>P2_DEPTNO</code> in <strong>Elementi da sottomettere</strong>.</p>')))
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Specificare un blocco anonimo PL/SQL di sola esecuzione che verr\00E0 eseguito sul server.</p>'),
unistr('<p>\00C8 possibile fare riferimento ad altri elementi di pagina o di applicazione dall''interno dell''applicazione mediante una sintassi di associazione (ad esempio <code>:P1_MY_ITEM</code>). \00C8 inoltre necessario includere gli elementi ai quali si fa rifer')
||'imento in <strong>Elementi pagina da sottomettere</strong>.</p>'))
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(2700703882467720.4415)
,p_plugin_id=>wwv_flow_imp.id(1811565602388283608.4415)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>1
,p_display_sequence=>11
,p_prompt=>'Codice JavaScript'
,p_attribute_type=>'MLE JAVASCRIPT'
,p_is_required=>true
,p_is_translatable=>false
,p_depending_on_attribute_id=>wwv_flow_imp.id(2700405449462251.4415)
,p_depending_on_has_to_exist=>true
,p_depending_on_condition_type=>'EQUALS'
,p_depending_on_expression=>'JAVASCRIPT'
,p_examples=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<dl><dt>Aumento dello stipendio del 3% per i dipendenti qualificati per l''aumento:</dt>',
'<dd><pre>',
'var rows;',
'function needsSalaryRaise( empno ) {',
'  // segnaposto per la logica complicata per calcolare se il dipendente necessita dell''aumento',
'  return true;',
'}',
'rows = apex.conn.execute( "select empno from emp where deptno = :deptno", { deptno: apex.env.P2_DEPTNO } ).rows;',
'for ( var row of rows ) {',
'  if ( needsSalaryRaise( row.EMPNO )) {',
'    apex.conn.execute( "update emp set sal = sal * 1.03 where empno = :empno", { empno: row.EMPNO } );',
'  }',
'}',
'</pre></dd>',
'</dl>',
unistr('<p>Per questo esempio \00E8 necessario immettere <code>P2_DEPTNO</code> in <strong>Elementi da sottomettere</strong>.</p>')))
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
